return ['domain'=>'tranzly','plural-forms'=>'nplurals=3; plural=(((((((0 == 0)) && ((((n == 0)) == 0))) && (((n % 1000000) == 0))) && ((0 == 0))) || ((((0 >= 0 && 0 <= 5)) == 0))) ? 1 : (((n == 1)) && ((0 == 0))) ? 0 : 2);','language'=>'it_IT','project-id-version'=>'tranzly','pot-creation-date'=>'2026-09-26T14:03:23+00:00','po-revision-date'=>'2026-09-26T14:03:23+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Tranzly'=>'Tranzly','https://zinndigital.com/wordpress-plugins/tranzly'=>'https://zinndigital.com/wordpress-plugins/tranzly','Multilingual WordPress, one post per language: linked translations of posts, pages, categories, media text, widgets and the site title, with your old Tranzly translations imported.'=>'WordPress multilingue, un articolo per lingua: traduzioni collegate di articoli, pagine, categorie, testo multimediale, widget e titolo del sito, con le Sue vecchie traduzioni Tranzly importate.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','AI providers'=>'Provider di IA','The makers of ChatGPT. A good all-rounder.'=>'I creatori di ChatGPT. Un ottimo tuttofare.','The makers of Claude. Strong at writing and careful reasoning.'=>'I creatori di Claude. Eccellenti nella scrittura e nel ragionamento accurato.','Google\'s Gemini models. Fast and inexpensive.'=>'I modelli Gemini di Google. Veloci e convenienti.','A European AI company with fast, inexpensive models.'=>'Un\'azienda europea di intelligenza artificiale con modelli veloci ed economici.','Low-cost models that are good at writing and code.'=>'Modelli a basso costo che eccellono nella scrittura e nel codice.','One key for models from many different providers.'=>'Una sola chiave per modelli di tantissimi provider diversi.','Any service that works like OpenAI\'s API, including a model running on your own computer or server.'=>'Qualsiasi servizio che funzioni come l\'API di OpenAI, compreso un modello in esecuzione sul proprio computer o server.','General (used when nothing more specific is set)'=>'Generale (utilizzato quando non è impostato nulla di più specifico)','Writing and rewriting'=>'Scrittura e riscrittura','Translation'=>'Traduzione','Code and CSS'=>'Codice e CSS','Sorry, you are not allowed to access this page.'=>'Siamo spiacenti, non disponi dell\'autorizzazione per accedere a questa pagina.','These settings are shared by every plugin that uses them: %s.'=>'Queste impostazioni sono condivise da ogni plugin che le utilizza: %s.','Your keys are encrypted in this site\'s database and are only ever sent to the provider you chose — never to us.'=>'Le Sue chiavi sono crittografate nel database di questo sito e vengono inviate esclusivamente al provider da Lei scelto, mai a noi.','Step 1 of 2: choose an AI provider'=>'Passaggio 1 di 2: scegli un provider di IA','You bring your own key, so you pay the provider directly for what you use. Not sure? Any of these works well; you can add more later.'=>'Utilizzate la vostra chiave, pagando così direttamente il fornitore per ciò che consumate. Non avete le idee chiare? Ognuna di queste opzioni funziona perfettamente; potrete aggiungerne altre in seguito.','Next'=>'Avanti','Step 2 of 2: connect %s'=>'Passaggio 2 di 2: collega %s','Enter the address of your OpenAI-compatible service, ending in /v1. A key is only needed if the service asks for one.'=>'Inserire l\'indirizzo del Suo servizio compatibile con OpenAI, terminando con /v1. Una chiave è necessaria solo se il servizio ne richiede una.','Open %s and sign in (or create a free account).'=>'Apri %s e accedi (o crea un account gratuito).','the %s API keys page'=>'la pagina delle chiavi API %s','Create a new key and copy it.'=>'Crea una nuova chiave e copiala.','Paste it below and press "Save and test". We send one tiny request to check it works.'=>'Incollalo qui sotto e premi "Salva e prova". Invieremo una piccolissima richiesta per verificarne il corretto funzionamento.','Most providers need a little credit on the account before a key works: %s.'=>'La maggior parte dei provider richiede un po\' di credito sull\'account prima che una chiave funzioni: %s.','add credit'=>'aggiungi credito','← Choose a different provider'=>'← Scegli un altro provider','Address'=>'Indirizzo','Saved key ends in …%s — paste a new one to replace it'=>'La chiave salvata termina con …%s — incollane una nuova per sostituirla','Key (optional)'=>'Chiave (facoltativo)','API key'=>'Chiave API','Save and test'=>'Salva e prova','Providers'=>'Provider','Provider'=>'Provider','Status'=>'Stato','Key'=>'Chiave','Get a key'=>'Ottieni una chiave','Test'=>'Test','Remove'=>'Rimuovi','Saved by a newer plugin version: update this plugin, or enter the key again.'=>'Salvato da una versione più recente del plugin: aggiornare questo plugin o inserire nuovamente la chiave.','The saved key can no longer be opened (the site\'s security keys changed). Enter it again.'=>'La chiave salvata non può più essere aperta (le chiavi di sicurezza del sito sono cambiate). Inseriscila di nuovo.','Not connected'=>'Non connesso','Connected — last test passed %s'=>'Connesso — ultimo test superato %s','Last test failed: %s'=>'Ultimo test fallito: %s','Connected — not tested yet'=>'Connesso — non ancora testato','Which model to use'=>'Quale modello utilizzare','★ marks our recommendation for that task. The list includes every model your key can use, read live from the provider.'=>'★ indica la nostra raccomandazione per quell\'attività. L\'elenco include tutti i modelli che la Sua chiave può utilizzare, letti in tempo reale dal provider.','— Recommended for the provider —'=>'Consigliato per il provider','Save models'=>'Salva modelli','Refresh the model lists from the providers'=>'Aggiorna gli elenchi dei modelli dai provider','best quality'=>'migliore qualità','lowest cost'=>'costo inferiore','fastest'=>'più veloce','Add a model yourself'=>'Aggiungi un modello tu stesso','A model came out today? Paste its exact name to use it straight away.'=>'È uscito un nuovo modello oggi? Incolla il suo nome esatto per usarlo subito.','Model name'=>'Nome del modello','Add model'=>'Aggiungi modello','Recommended models list'=>'Elenco modelli consigliati','The recommended models list could not be verified, so no recommendations are shown. Reinstall the plugin, or turn on daily updates below.'=>'Impossibile verificare l\'elenco dei modelli consigliati, quindi non viene mostrato alcun consiglio. Reinstallare il plugin o attivare gli aggiornamenti giornalieri qui sotto.','The list in use was published on %s. Each plugin update brings a fresh one.'=>'L\'elenco in uso è stato pubblicato il %s. Ogni aggiornamento del plugin ne fornisce uno nuovo.','Also check Zinn Digital® once a day for an updated list.'=>'Controlla anche Zinn Digital® una volta al giorno per un elenco aggiornato.','Only a plain download request is sent: no key, no site address, nothing about your content. The list is signed, and a list that fails the signature check is ignored.'=>'Viene inviata solo una semplice richiesta di download: nessuna chiave, nessun indirizzo del sito, nulla sui Suoi contenuti. L\'elenco è firmato e un elenco che non supera il controllo della firma viene ignorato.','Last checked %1$s: %2$s.'=>'Ultimo controllo %1$s: %2$s.','Save, and check now if turned on'=>'Salva e verifica ora se è attivato','a newer list was installed'=>'è stata installata una lista più recente','already up to date'=>'già aggiornato','the download failed the signature check and was ignored'=>'il download non ha superato il controllo della firma ed è stato ignorato','Zinn Digital® could not be reached; the current list stays in use'=>'Non è stato possibile raggiungere Zinn Digital®; l\'elenco corrente rimane in uso','turned off'=>'disattivato','Open'=>'Apri','Check their status page'=>'Controlla la loro pagina dello stato','Open your billing page'=>'Apra la Sua pagina di fatturazione','Open your API keys page'=>'Apra la pagina delle tue chiavi API','Open the AI settings'=>'Apri le impostazioni IA','Sorry, you are not allowed to do that.'=>'Senza autorizzazione per eseguire questa operazione.','Unknown provider.'=>'Provider sconosciuto.','Enter the address of your service, for example http://localhost:11434/v1.'=>'Inserisca l\'indirizzo del Suo servizio, ad esempio http://localhost:11434/v1.','That does not look like an API key. Copy it again, without spaces.'=>'Non sembra una chiave API. Copiala di nuovo, senza spazi.','Paste your API key first.'=>'Incolli prima la Sua chiave API.','Key removed.'=>'Chiave rimossa.','Models saved.'=>'Modelli salvati.','Enter the model\'s exact name, for example as the provider\'s documentation writes it.'=>'Inserisci il nome esatto del modello, ad esempio come è scritto nella documentazione del provider.','Added %s. Choose it under "Which model to use".'=>'Aggiunto %s. Sceglilo nella sezione "Quale modello usare".','Model removed.'=>'Modello rimosso.','Daily updates are off. The list that came with the plugin is used.'=>'Gli aggiornamenti giornalieri sono disattivati. Viene utilizzata la lista fornita con il plugin.','Checked: %s.'=>'Selezionati: %s.','Model lists refreshed.'=>'Elenchi dei modelli aggiornati.','Your AI key was saved by a newer version of one of your plugins. Update this plugin, or enter the key again in the AI settings.'=>'La Sua chiave AI è stata salvata da una versione più recente di uno dei Suoi plugin. Aggiorni questo plugin o inserisca nuovamente la chiave nelle impostazioni AI.','Your saved AI key can no longer be opened (the site\'s security keys changed). Enter it again in the AI settings.'=>'La chiave IA salvata non può più essere aperta (le chiavi di sicurezza del sito sono cambiate). Inseriscila di nuovo nelle impostazioni IA.','AI is not set up yet. Add a key for an AI provider in the AI settings.'=>'L\'IA non è ancora configurata. Aggiungi una chiave per un provider di IA nelle impostazioni dell\'IA.','No model is chosen for this task. Pick one in the AI settings.'=>'Nessun modello è selezionato per questa attività. Scegline uno nelle impostazioni dell\'intelligenza artificiale.','That AI provider is not supported by this version of the plugin.'=>'Quel provider di IA non è supportato da questa versione del plugin.','This site could not reach your AI service. Check that it is running and that its address is reachable from your web server (a service on your own computer is not reachable from a hosted site).'=>'Questo sito non è riuscito a raggiungere il vostro servizio di intelligenza artificiale. Verificate che sia in esecuzione e che il suo indirizzo sia raggiungibile dal vostro server web (un servizio sul vostro computer non è raggiungibile da un sito ospitato).','This site could not reach %s. Check their status page; if they are up, your host may be blocking outgoing connections, or the address is wrong.'=>'Questo sito non ha potuto raggiungere %s. Controlla la loro pagina di stato; se sono attivi, il tuo host potrebbe bloccare le connessioni in uscita o l\'indirizzo potrebbe essere errato.','%s says your account has no credit or quota left. Add credit or raise your limit in your account with them, then try again.'=>'%s indica che il Suo account non ha credito o quota residua. Aggiunga credito o aumenti il limite nel Suo account con loro, quindi riprovi.','%s did not accept your key. It may be mistyped, revoked or expired. Create a new key and paste it here.'=>'%s non ha accettato la Sua chiave. Potrebbe essere stata digitata male, revocata o scaduta. Crei una nuova chiave e la incolli qui.','%s refused this request for your key. The key may not have access to this model or feature, or your account needs verifying.'=>'%s ha rifiutato questa richiesta per la Sua chiave. La chiave potrebbe non avere accesso a questo modello o a questa funzione, oppure il Suo account deve essere verificato.','The model "%1$s" is not available from %2$s for your key. Choose another model in the AI settings.'=>'Il modello "%1$s" non è disponibile da %2$s per la Sua chiave. Scegli un altro modello nelle impostazioni dell\'IA.','Your %2$s plan does not include the model "%1$s". Choose another model in the AI settings, or upgrade your plan with them.'=>'Il Suo piano %2$s non include il modello "%1$s". Slices un altro modello nelle impostazioni dell\'IA oppure effettui l\'upgrade del piano con loro.','%s is limiting how fast your key can send requests. Wait a minute and try again, or raise your rate limit with them.'=>'%s sta limitando la velocità con cui la Sua chiave può inviare richieste. Attenda un minuto e riprovi, oppure aumenti il limite di frequenza con loro.','%s is having problems right now (an outage or overload on their side). Nothing is wrong with your settings. Try again shortly.'=>'%s sta riscontrando problemi in questo momento (un\'interruzione o un sovraccarico dal loro lato). Non c\'è alcun problema con le Sue impostazioni. Riprovi a breve.','The AI request failed for a reason we could not identify. Try again; if it keeps happening, contact support with the details below.'=>'La richiesta IA non è riuscita per un motivo che non siamo riusciti a identificare. Riprova; se il problema persiste, contatta il supporto fornendo i dettagli sottostanti.','The AI provider answered in a form this plugin could not read. Try again; if it keeps happening, choose another model or contact support.'=>'Il provider di intelligenza artificiale ha risposto in un formato che questo plugin non è riuscito a leggere. Riprova; se il problema persiste, scegli un altro modello o contatta il supporto.','Custom (OpenAI-compatible)'=>'Personalizzato (compatibile con OpenAI)','Save a key for this provider first.'=>'Salvare prima una chiave per questo provider.','Your key works, but the provider lists no text model for it. Add a model yourself below.'=>'La Sua chiave funziona, ma il provider non elenca alcun modello di testo per essa. Aggiunga Lei stesso un modello qui sotto.','Connected. %1$s answered using %2$s. Your AI features are ready to use.'=>'Connesso. %1$s ha risposto utilizzando %2$s. Le Sue funzionalità di intelligenza artificiale sono pronte per l\'uso.','Your user role is not allowed to use AI on this site. Ask an administrator.'=>'Il Suo ruolo utente non è autorizzato a utilizzare l\'IA su questo sito. Si rivolga a un amministratore.','This site has reached its monthly AI spending limit. An administrator can raise it in the AI settings.'=>'Questo sito ha raggiunto il limite di spesa mensile per l\'intelligenza artificiale. Un amministratore può aumentarlo nelle impostazioni dell\'IA.','This site has reached its monthly limit of AI requests. An administrator can raise it in the AI settings.'=>'Questo sito ha raggiunto il suo limite mensile di richieste IA. Un amministratore può aumentarlo nelle impostazioni IA.','Usage and cost'=>'Utilizzo e costi','The log, limits and role permissions apply to AI used through: %s.'=>'Il registro, i limiti e i permessi dei ruoli si applicano all\'intelligenza artificiale utilizzata tramite: %s.','Costs are approximate, worked out from published prices; a model with no known price counts as zero.'=>'I costi sono approssimativi, calcolati dai prezzi pubblicati; un modello senza prezzo noto viene conteggiato come zero.','This month: %1$s requests, about %2$s.'=>'Questo mese: %1$s richieste, circa %2$s.','When'=>'Quando','Who'=>'Chi','Used for'=>'Utilizzato per','Model'=>'Modello','Tokens in / out'=>'Token in / out','About'=>'Informazioni','Result'=>'Risultato','No AI requests have been made yet.'=>'Non è stata ancora effettuata alcuna richiesta IA.','Done'=>'Completato','Limits and permissions'=>'Limiti e permessi','Monthly spending limit (US dollars)'=>'Limite di spesa mensile (US dollari)','Leave empty for no limit. AI stops for the rest of the month once the approximate cost reaches it.'=>'Lasciare vuoto per nessun limite. L\'intelligenza artificiale si ferma per il resto del mese una volta raggiunto il costo approssimativo.','Monthly request limit'=>'Limite mensile delle richieste','Leave empty for no limit.'=>'Lasciare vuoto per nessun limite.','Who may use AI'=>'Chi può utilizzare l\'IA','Tick none to let everyone who can use the plugin\'s features use AI. Administrators can always use it.'=>'Non selezionare nulla per consentire a chiunque possa utilizzare le funzionalità del plugin di usare l\'IA. Gli amministratori possono utilizzarla sempre.','Save limits and permissions'=>'Salva limiti e permessi','Limits and permissions saved.'=>'Limiti e permessi salvati.','That language is not one of this site\'s languages.'=>'Questa lingua non è tra quelle supportate da questo sito.','A translation must be the same kind of content as the original.'=>'Una traduzione deve essere dello stesso tipo di contenuto dell\'originale.','Choose one of the site\'s other languages.'=>'Scegli una delle altre lingue del sito.','The admin screen\'s scripts are missing from this copy of the plugin. Reinstall it from a released package.'=>'Gli script della schermata di amministrazione mancano da questa copia del plugin. Reinstallalo da un pacchetto rilasciato.','This screen needs JavaScript.'=>'Questo schermo richiede JavaScript.','Choose a language'=>'Scegli una lingua','Upgrade'=>'Aggiorna','Pricing'=>'Prezzi','Start Trial'=>'Inizia la prova gratuita','Account'=>'Account','Contact Us'=>'Contattaci','Affiliation'=>'Affiliazione','the kind of softwarePlugin'=>'Plugin','greetingHey %s,'=>'Ciao %s,','Opt in to get email notifications for security & feature updates, educational content, and occasional offers, and to share some basic WordPress environment info. This will help us make the %s more compatible with your site and better at doing what you need it to.'=>'Accetti di ricevere notifiche via email per aggiornamenti di sicurezza e funzionalità, contenuti formativi e offerte occasionali, e di condividere alcune informazioni di base sull\'ambiente WordPress. Ciò ci aiuterà a rendere il %s più compatibile con il Suo sito e più efficiente nel soddisfare le Sue esigenze.','Opt in to get email notifications for security & feature updates, educational content, and occasional offers, and to share some basic WordPress environment info.'=>'Iscriviti per ricevere notifiche via email su aggiornamenti di sicurezza e funzionalità, contenuti formativi e offerte occasionali, e per condividere alcune informazioni di base sull\'ambiente WordPress.','If you skip this, that\'s okay! %1$s will still work just fine.'=>'Se salti questo passaggio, nessun problema! %1$s continuerà a funzionare perfettamente.','Allow & Continue'=>'Consenti e continua','verbSkip'=>'Salta','Skipping, please wait'=>'Salto in corso, attendere prego','Continue'=>'Continua','Please wait'=>'Attendere prego','as activating pluginActivating'=>'Attivazione','This will allow %s to'=>'Questo consentirà a %s di','Privacy Policy'=>'Informativa sulla privacy','Terms of Service'=>'Termini di servizio','License Agreement'=>'Contratto di licenza','Have a license key?'=>'Disponi di una chiave di licenza?','Activate License'=>'Attiva licenza','View Basic Profile Info'=>'Visualizza informazioni di base sul profilo','Your WordPress user\'s: first & last name, and email address'=>'I dati utente del Suo WordPress: nome, cognome e indirizzo email','View Basic Website Info'=>'Visualizza informazioni di base sul sito web','Homepage URL & title, WP & PHP versions, and site language'=>'URL e titolo della homepage, versioni di WP e PHP e lingua del sito','View Basic %s Info'=>'Visualizza informazioni di base %s','Current %s & SDK versions, and if active or uninstalled'=>'Versioni correnti di %s e SDK, e se attivo o disinstallato','Newsletter'=>'Newsletter','Updates, announcements, marketing, no spam'=>'Aggiornamenti, annunci, marketing, niente spam','View Diagnostic Info'=>'Visualizza informazioni diagnostiche','WordPress & PHP versions, site language & title'=>'Versioni di WordPress & PHP, lingua e titolo del sito','View Plugins & Themes List'=>'Visualizza elenco di plugin e temi','Names, slugs, versions, and if active or not'=>'Nomi, slug, versioni e stato di attivazione','optional'=>'facoltativo','Never miss an important update'=>'Non perdere mai un aggiornamento importante','We have introduced this opt-in so you never miss an important update and help us make the %s more compatible with your site and better at doing what you need it to.'=>'Abbiamo introdotto questa opzione di attivazione per fare in modo che non perdiate mai un aggiornamento importante e per aiutarci a rendere %s più compatibile con il vostro sito e più efficace nel soddisfare le vostre esigenze.','Thank you for updating to %1$s v%2$s!'=>'Grazie per aver aggiornato a %1$s v%2$s!','The prefix must be 1 to 8 lowercase letters or digits, start with a letter, and must not name the plugin.'=>'Il prefisso deve essere composto da 1 a 8 lettere minuscole o cifre, iniziare con una lettera e non deve coincidere con il nome del plugin.','"%s" is not a language code. Use a WordPress locale such as fr_FR or de_DE.'=>'"%s" non è un codice lingua. Utilizza un locale di WordPress come fr_FR o de_DE.','List at least one language.'=>'Elenca almeno una lingua.','You are not allowed to translate this item.'=>'Non è consentito tradurre questo elemento.','This item already has a version in that language.'=>'Questo elemento ha già una versione in quella lingua.','That translation engine is not available on this site.'=>'Quel motore di traduzione non è disponibile su questo sito.','Different engines per language, automatic fallback and spending caps are Tranzly Pro features.'=>'Motori diversi per lingua, fallback automatico e limiti di spesa sono funzionalità di Tranzly Pro.','Each language must be one of the site\'s languages, with an available engine.'=>'Ogni lingua deve essere una delle lingue del sito, con un motore disponibile.','The fallback list may only name available engines.'=>'L\'elenco di fallback può indicare solo motori disponibili.','A monthly cap is an amount in US dollars, zero or more, for an available engine.'=>'Un limite mensile è un importo in US dollari, pari a zero o superiore, per un motore disponibile.','Preferred translations and tone per language are Tranzly Pro features. The do-not-translate list is free.'=>'Le traduzioni preferite e il tono per lingua sono funzionalità di Tranzly Pro. L\'elenco dei termini da non tradurre è gratuito.','Glossary entries must be grouped by one of the site\'s languages.'=>'Le voci del glossario devono essere raggruppate per una delle lingue del sito.','Tone is set per site language: formality default, more or less, plus optional instructions.'=>'Il tono è impostato per lingua del sito: formalità predefinita, più o meno, più istruzioni opzionali.','The value for %s is not one of the allowed choices.'=>'Il valore per %s non è una delle scelte consentite.','The background queue is not available on this site.'=>'La coda in background non è disponibile su questo sito.','A translation job runs as the person who starts it, so a user must be signed in.'=>'Un lavoro di traduzione viene eseguito dall\'utente che lo avvia, quindi è necessario aver effettuato l\'accesso.','There is nothing you are allowed to translate in that selection.'=>'Non c\'è nulla che ti sia permesso di tradurre in quella selezione.','That item is not part of a translation job.'=>'Quel elemento non fa parte di un lavoro di traduzione.','You are not allowed to change that translation.'=>'Non è consentito modificare tale traduzione.','This item\'s group already has a %1$s version (#%2$d).'=>'Il gruppo di questo elemento ha già una versione %1$s (#%2$d).','An item cannot be its own translation.'=>'Un elemento non può essere la traduzione di se stesso.','That item is already a translation of something else. Unlink it first.'=>'Quel elemento è già la traduzione di un altro. Scollegalo prima.','The translation link could not be saved.'=>'Non è stato possibile salvare il link di traduzione.','That text cannot be translated here.'=>'Quel testo non può essere tradotto qui.','That media text cannot be translated here.'=>'Quel testo multimediale non può essere tradotto qui.','A translation can be published or kept as a draft.'=>'Una traduzione può essere pubblicata o salvata come bozza.','You are not allowed to publish this kind of content.'=>'Non è consentito pubblicare questo tipo di contenuto.','This item is already written in that language.'=>'Questo elemento è già scritto in quella lingua.','This translation was edited by a person (or imported), so it is protected. Unlock it to translate it again.'=>'Questa traduzione è stata modificata da una persona (o importata), quindi è protetta. Sbloccala per tradurla di nuovo.','No translation engine is set up yet. Add a key for one in Tranzly → Engines.'=>'Non è ancora stato configurato alcun motore di traduzione. Aggiungine una chiave in Tranzly → Motori.','That translation engine is not set up yet: add its key first.'=>'Quel motore di traduzione non è ancora configurato: aggiungi prima la sua chiave.','The same text is being translated by another job right now; this item will use that answer.'=>'Lo stesso testo è attualmente in fase di traduzione da parte di un altro processo; questo elemento utilizzerà quel risultato.','No translation engine could take this item.'=>'Nessun motore di traduzione è riuscito a elaborare questo elemento.','The engine did not return a translation for every part of this item. Nothing was changed.'=>'Il motore non ha restituito una traduzione per ogni parte di questo elemento. Non è stato modificato nulla.','AI model'=>'Modello IA','AI model (%1$s %2$s)'=>'Modello IA (%1$s %2$s)','%s is having problems right now. Try again shortly, or use another engine.'=>'%s sta riscontrando problemi in questo momento. Riprova a breve o usa un altro motore.','Your site could not reach %s. Check that it can make outgoing connections, then try again.'=>'Il Suo sito non è riuscito a raggiungere %s. Verifichi che possa stabilire connessioni in uscita, quindi riprovi.','%s did not accept your API key. Check the key in Tranzly → Engines.'=>'%s non ha accettato la Sua chiave API. Verifichi la chiave in Tranzly → Engines.','Your %s account has used up its quota or balance. Top it up with them, or use another engine.'=>'Il Suo account %s ha esaurito la quota o il saldo. Effettui una ricarica con essi, oppure utilizzi un altro motore.','%s asked us to slow down. It will be tried again automatically.'=>'%s ci ha chiesto di rallentare. L\'operazione verrà ripetuta automaticamente.','This text is too long for %s in one go. Split the content, or use another engine.'=>'Questo testo è troppo lungo per %s in un\'unica soluzione. Dividi il contenuto o utilizza un altro motore.','%s refused to translate this content. Try another engine, or translate it by hand.'=>'%s ha rifiutato di tradurre questo contenuto. Prova un altro motore o traducilo manualmente.','%s does not translate this language. Choose another engine for it.'=>'%s non traduce questa lingua. Scegline un altro motore.','This month\'s spending cap for %s is reached, so nothing more was sent to it. Raise the cap in Tranzly → Engines, or wait until next month.'=>'È stato raggiunto il limite di spesa di questo mese per %s, quindi non sono stati inviati ulteriori dati. Aumenta il limite in Tranzly → Engines o attendi il mese prossimo.','The translation with %s failed for a reason Tranzly could not identify. The details are below.'=>'La traduzione con %s non è riuscita per un motivo che Tranzly non è riuscito a identificare. I dettagli sono riportati di seguito.','An engine id must be lowercase letters, digits and hyphens.'=>'Un ID motore deve essere composto da lettere minuscole, cifre e trattini.','Built by Neil Lock, CEO of Zinn Digital® Ltd'=>'Creato da Neil Lock, CEO di Zinn Digital® Ltd','Version %s'=>'Versione %s','Tranzly website'=>'Sito web Tranzly','Zinn Digital® website'=>'sito web di Zinn Digital®','Settings saved.'=>'Impostazioni salvate.','See the Pro plans and pricing'=>'Visualizza i piani Pro e i prezzi','Languages'=>'Lingue','The first language is the one your content is written in. Visitors switch with the language switcher block.'=>'La prima lingua è quella in cui sono scritti i Suoi contenuti. I visitatori passano da una lingua all\'altra con il blocco di selezione della lingua.','(default)'=>'(predefinito)','Locale code'=>'Codice lingua','For example fr_FR'=>'Ad esempio fr_FR','Name (optional)'=>'Nome (facoltativo)','For example Français'=>'Ad esempio Français','Add language'=>'Aggiungi lingua','Front-end output'=>'Output di front-end','Class name prefix'=>'Prefisso nome classe','Every class name the plugin prints on your pages starts with this prefix, so the pages do not reveal which plugin built them. 1 to 8 lowercase letters or digits, starting with a letter.'=>'Ogni nome di classe stampato dal plugin sulle vostre pagine inizia con questo prefisso, in modo che le pagine non rivelino quale plugin le ha create. Da 1 a 8 lettere minuscole o cifre, che iniziano con una lettera.','Beta updates'=>'Aggiornamenti beta','This site receives beta versions as updates.'=>'Questo sito riceve versioni beta come aggiornamenti.','This site receives stable versions only.'=>'Questo sito riceve solo versioni stabili.','Change this on the Account page'=>'Modifica questa voce nella pagina Account','Beta versions are offered to licensed Pro installations that are connected to their account. Once connected, you can join from the Account page.'=>'Le versioni beta sono offerte alle installazioni Pro con licenza che sono collegate al proprio account. Una volta connesse, puoi partecipare dalla pagina Account.','Save settings'=>'Salva impostazioni','First engine that is set up'=>'Primo motore configurato','Key saved. It is stored encrypted and never shown again.'=>'Chiave salvata. Viene memorizzata in modo crittografato e non verrà più mostrata.','Engine settings saved.'=>'Impostazioni del motore salvate.','Glossary saved.'=>'Glossario salvato.','Your keys'=>'Le Sue chiavi','Tranzly calls the translation services with your own account. Keys are stored encrypted in your database and are only ever sent to the service they belong to. AI model keys are set in the AI settings.'=>'Tranzly chiama i servizi di traduzione con il Suo account. Le chiavi vengono memorizzate in modo crittografato nel Suo database e inviate esclusivamente al servizio a cui appartengono. Le chiavi dei modelli di IA si impostano nelle impostazioni dell\'IA.','%s API key'=>'Chiave API %s','Saved: %s. Enter a new key to replace it, or save an empty field to remove it.'=>'Salvato: %s. Inserisci una nuova chiave per sostituirla, oppure salva un campo vuoto per rimuoverla.','No key saved.'=>'Nessuna chiave salvata.','Azure region (leave empty for a global resource)'=>'Area geografica Azure (lasciare vuoto per una risorsa globale)','Save key'=>'Salva chiave','Check my DeepL usage'=>'Verifica l\'utilizzo di DeepL','%1$s of %2$s characters used this billing period.'=>'%1$s di %2$s caratteri utilizzati in questo ciclo di fatturazione.','Which engine translates'=>'Quale motore traduce','No engine is set up yet. Save a key above (or set up an AI model) to start translating.'=>'Nessun motore è stato ancora configurato. Salva una chiave sopra (o configura un modello di IA) per iniziare a tradurre.','Default engine'=>'Motore predefinito','A different engine per language, automatic fallback and monthly spending caps are Tranzly Pro features.'=>'Un motore diverso per lingua, il fallback automatico e i tetti di spesa mensili sono funzionalità di Tranzly Pro.','Engine for %s'=>'Motore per %s','The default engine'=>'Il motore predefinito','If an engine fails or reaches a limit, try these next, in this order'=>'Se un motore si guasta o raggiunge un limite, prova questi passaggi nell\'ordine indicato','Monthly spending caps'=>'Limiti di spesa mensili','When an engine reaches its cap, nothing more is sent to it until next month and the failed-translation report says why. Leave empty for no cap.'=>'Quando un motore raggiunge il suo limite, non gli viene inviato più nulla fino al mese prossimo e il rapporto sulle traduzioni non riuscite ne spiega il motivo. Lasciare vuoto per nessun limite.','%1$s (spent this month: $%2$s)'=>'%1$s (speso questo mese: $%2$s)','Save caps'=>'Salva maiuscole','Glossary and words never translated'=>'Glossario e parole mai tradotte','Never translate these words (one per line)'=>'Non tradurre mai queste parole (una per riga)','Brand and product names stay exactly as they are, with every engine.'=>'I nomi di marchi e prodotti rimangono esattamente come sono, con ogni motore.','Preferred translations and tone per language are Tranzly Pro features.'=>'Le traduzioni preferite e il tono per lingua sono funzionalità di Tranzly Pro.','Preferred translations (one per line: term = translation)'=>'Traduzioni preferite (una per riga: termine = traduzione)','Formality'=>'Formalità','Default'=>'Predefinito','Formal'=>'Formale','Informal'=>'Informale','Style instructions (audience, brand voice)'=>'Istruzioni di stile (pubblico, tono del marchio)','Save glossary'=>'Salva glossario','Job started with %d translations to do. It runs in the background: you can close this page.'=>'L\'attività è iniziata con %d traduzioni da eseguire. Viene eseguita in background: puoi chiudere questa pagina.','Queued again.'=>'Di nuovo in coda.','Running'=>'In esecuzione','Finished'=>'Completato','Cancelled'=>'Annullato','Translate in the background'=>'Traduci in background','Set up a translation engine in the Engines tab first.'=>'Configurare prima un motore di traduzione nella scheda Motori.','Translate every'=>'Traduci tutto','Into'=>'In','With'=>'Con','Each language’s own engine'=>'Il motore di ogni lingua','Publish the translations (otherwise they are saved as drafts)'=>'Pubblica le traduzioni (altrimenti verranno salvate come bozze)','Estimate the cost'=>'Stima il costo','%1$d posts, %2$s characters. The price for this engine is not known in advance.'=>'%1$d post, %2$s caratteri. Il prezzo di questo motore non è noto in anticipo.','%1$d posts, %2$s characters: about $%3$s on your own account.'=>'%1$d post, %2$s caratteri: circa $%3$s sul Suo account.','Start translating'=>'Inizia la traduzione','Jobs'=>'Lavori','No translation jobs yet.'=>'Nessun lavoro di traduzione ancora.','Job %1$d — %2$s'=>'Attività %1$d — %2$s','%1$d of %2$d translated, %3$d failed, %4$d skipped (protected or already in that language)'=>'%1$d di %2$d tradotti, %3$d non riusciti, %4$d ignorati (protetti o già in quella lingua)','Stop this job'=>'Arresta questo lavoro','See what failed and why'=>'Scopri cosa non ha funzionato e perché','Content'=>'Contenuto','Language'=>'Lingua','What went wrong'=>'Cosa è andato storto','Fix it'=>'Risolvi','Details'=>'Dettagli','Retry with'=>'Riprova con','The same engine'=>'Lo stesso motore','Retry'=>'Riprova','Translate by hand'=>'Traduci manualmente','Languages and settings'=>'Lingue e impostazioni','Engines'=>'Motori','Translation jobs'=>'Lavori di traduzione','Add a second language under Tranzly in the admin menu, and the switcher appears here.'=>'Aggiungi una seconda lingua in Tranzly dal menu di amministrazione e il selettore comparirà qui.','Switcher'=>'Selettore','Accessible label'=>'Etichetta accessibile','block titleLanguage switcher'=>'Selettore lingua','block descriptionLinks to this page in each of the site\'s languages. It renders nothing until two or more languages are listed.'=>'Link a questa pagina in ciascuna lingua del sito. Non visualizza nulla finché non vengono elencate due o più lingue.','block keywordlanguage'=>'lingua','block keywordswitcher'=>'selettore','block keywordtranslation'=>'traduzione']];